412	  /// Returns the parent plugin if the current project is a plugin's example app,
413	  /// or `null` otherwise.
414	  static Plugin? _loadPluginFromExampleProject({
415	    required FileSystem fileSystem,
416	    required Logger logger,
417	    required FlutterProject project,
418	    required List<Plugin> plugins,
419	  }) {
420	    final Directory projectDir = project.directory;
421	    if (!projectDir.path.endsWith('example')) {
422	      return null;
423	    }
424	
425	    final Directory parentDir = projectDir.parent;
426	    final File parentPubspec = parentDir.childFile('pubspec.yaml');
427	    if (!parentPubspec.existsSync()) {
428	      return null;
429	    }
430	
431	    final FlutterManifest? parentManifest;
432	    try {
433	      parentManifest = FlutterManifest.createFromPath(
434	        parentPubspec.path,
435	        fileSystem: fileSystem,
436	        logger: logger,
437	      );
438	    } on Exception catch (e) {
439	      logger.printTrace('Failed to parse parent pubspec for SwiftPM validation: $e');
440	      return null;
441	    }
442	
443	    if (parentManifest == null || !parentManifest.isPlugin) {
444	      return null;
445	    }
446	
447	    final String pluginName = parentManifest.appName;
448	    return plugins.where((Plugin p) => p.name == pluginName).firstOrNull;
